    if (model === null || model === undefined)
      continue;
    const providerID = model.providerID;
    const modelID = model.modelID ?? model.id;
    if (typeof providerID !== "string" || providerID === "")
      continue;
    if (typeof modelID !== "string" || modelID === "")
      continue;
    if (!Array.isArray(model.cost) || model.cost.length === 0)
      continue;
    const tiers = [];
    for (const cost of model.cost) {
      if (cost === null || cost === undefined)
        continue;
      let tier;
      if (cost.tier !== undefined) {
        const size = cost.tier.size;
        if (typeof size !== "number" || !Number.isFinite(size))
          continue;
        tier = { ...cost.tier.type !== undefined ? { type: cost.tier.type } : {}, size };
      }
      tiers.push({
        ...tier !== undefined ? { tier } : {},
        input: money(cost.input),
        output: money(cost.output),
        cacheRead: money(cost.cache?.read),
        cacheWrite: money(cost.cache?.write)
